getAllRegionsAtLine(lineNumber, filter) {
        const result = [];
        if (this.c) {
            let index = this.c.findRange(lineNumber);
            let level = 1;
            while (index >= 0) {
                const current = this.c.toRegion(index);
                if (!filter || filter(current, level)) {
                    result.push(current);
                }
                level++;
                index = current.parentIndex;
            }
        }
        return result;
    }
